with sharing public class ContactDomainService {

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> result = new Map<String, List<Contact>>();

        // Handle null or empty set
        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        // Query contacts for the given accounts
        // 'with sharing' respects record-level sharing
        // WITH USER_MODE respects field-level security
        List<Contact> contacts = [
            SELECT Id, Email, AccountId 
            FROM Contact 
            WHERE AccountId IN :accountIds 
            AND Email != null 
            AND Email != ''
            WITH USER_MODE
        ];

        // Group contacts by email domain
        for (Contact contact : contacts) {
            String domain = extractDomain(contact.Email);
            if (domain != null) {
                if (!result.containsKey(domain)) {
                    result.put(domain, new List<Contact>());
                }
                result.get(domain).add(contact);
            }
        }

        return result;
    }

    private static String extractDomain(String email) {
        if (email == null || email.trim().length() == 0) {
            return null;
        }

        Integer atIndex = email.indexOf('@');
        if (atIndex == -1 || atIndex == email.length() - 1) {
            // Invalid email format - no @ or @ at end
            return null;
        }

        String domain = email.substring(atIndex + 1).toLowerCase().trim();
        return domain.length() > 0 ? domain : null;
    }
}
