public class ErpAccountSyncJob implements Queueable {
    private Set<Id> accountIds;
    private Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before doing work
        System.attachFinalizer(new ErpSyncFinalizer(this.accountIds, this.attempt));

        // Get accounts and update them
        List<Account> accountsToUpdate = [
            SELECT Id, Description
            FROM Account
            WHERE Id IN :accountIds
        ];

        for (Account acc : accountsToUpdate) {
            acc.Description = 'Synced to ERP';
        }

        // Save all-or-nothing; if any fails, the exception will propagate
        update accountsToUpdate;
    }
}
