public class ErpCustomerSync implements Queueable, Database.AllowsCallouts {
    private List<Account> accounts;

    public ErpCustomerSync(List<Account> accounts) {
        this.accounts = new List<Account>(accounts);
    }

    public void execute(QueueableContext context) {
        // Process accounts in batches respecting ERP API limit (200 per request)
        Integer batchSize = 200;
        List<Account> batch = new List<Account>();

        for (Account account : accounts) {
            batch.add(account);
            if (batch.size() == batchSize) {
                sendBatch(batch);
                batch = new List<Account>();
            }
        }

        // Send remaining accounts
        if (!batch.isEmpty()) {
            sendBatch(batch);
        }
    }

    private void sendBatch(List<Account> batch) {
        List<Map<String, Object>> customers = new List<Map<String, Object>>();

        for (Account account : batch) {
            Map<String, Object> customer = new Map<String, Object>();
            customer.put('salesforceId', account.Id);
            customer.put('name', account.Name);
            customer.put('country', account.BillingCountry);
            customers.add(customer);
