            body += 'Close Date: ' + (opp.CloseDate != null ? opp.CloseDate.format() : 'Not specified');
            email.setPlainTextBody(body);

            emails.add(email);
        }

        // Send all emails in a single invocation
        Messaging.SendEmailResult[] results = Messaging.sendEmail(emails);

        // Count successful sends
