import { LightningElement, track } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    @track searchTerm = '';
    @track results = [];
    @track error = null;

    debounceTimer = null;
    currentRequestId = 0;
    isConnected = true;

    disconnectedCallback() {
        this.isConnected = false;
        this.clearDebounce();
    }

    handleSearchInput(event) {
        const value = event.target.value;
        this.searchTerm = value;
        this.error = null;

        this.clearDebounce();

        const trimmedValue = value.trim();

        // If less than 2 characters, clear results and return
        if (trimmedValue.length < 2) {
            this.results = [];
            return;
        }

        // Increment request ID for this search
        this.currentRequestId++;
        const requestId = this.currentRequestId;

        // Set debounce timer for 300ms
        this.debounceTimer = setTimeout(() => {
            this.performSearch(trimmedValue, requestId);
        }, 300);
    }

    clearDebounce() {
        if (this.debounceTimer) {
            clearTimeout(this.debounceTimer);
            this.debounceTimer = null;
        }
    }

    async performSearch(searchTerm, requestId) {
        // Do not proceed if component is disconnected
        if (!this.isConnected) {
            return;
        }

        this.error = null;

        try {
            const response = await searchContacts({ searchTerm });

            // Only update results if this is the most recent request and component is still connected
            if (requestId === this.currentRequestId && this.isConnected) {
                this.results = response;
            }
        } catch (err) {
            // Only update error if this is the most recent request and component is still connected
            if (requestId === this.currentRequestId && this.isConnected) {
                this.error = err;
                this.results = [];
            }
        }
    }
}
