            Set<Id> accountIds = new Set<Id>();
            for (SObject sObj : triggerNew) {
                Contact contact = (Contact) sObj;
                if (contact.AccountId != null) {
                    accountIds.add(contact.AccountId);
                }
            }

            // Query accounts with all fields needed by dependent actions
            if (!accountIds.isEmpty()) {
                queries.accountsById = new Map<Id, Account>(
                    [SELECT Id, BillingStreet, BillingCity, BillingPostalCode, 
                            BillingCountry, AccountSource 
                     FROM Account 
                     WHERE Id IN :accountIds]
                );
            } else {
                queries.accountsById = new Map<Id, Account>();
